def finding(item, n, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(n + 5) % len(KINDS)], KINDS[(n + 13) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as source-qualified assessment context while subject, dataset, contract, execution, issue, remediation, certificate, audit and records masters remain external.",
            "source_refs": refs,
            "questions": [
              {"id": f"{fid}-q01", "text": f"What stable identity, assessment version, typed value and explicit unknown establish {low}?", "kind": kinds[0], "answer_data": ["assessment, subject and external master identifiers", "typed value, unit, scale, schema or profile", "unknown, unavailable, disputed and not-applicable states"]},
              {"id": f"{fid}-q02", "text": f"Who defined, measured, asserted, reviewed, approved or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["actor, agent, role, organization and contact", "purpose, stakeholder, authority, policy and access", "conflict, exception, escalation and accountability"]},
              {"id": f"{fid}-q03", "text": f"Which phenomenon, reference, execution, result, effective, published, recorded, ingested and knowledge times, evidence and uncertainty qualify {low}?", "kind": kinds[2], "answer_data": ["distinct subject, observation and assessment times", "method, evidence, confidence, uncertainty and limitation", "successor, correction, retention and audit"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed assessment data for {low}, qualified by subject version, purpose, method, source, authority, time, uncertainty and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned assessment evidence for {low}.", "media_or_form": ["logical data-quality assessment assertion", "definition, observation, result, verdict, evidence, exception, correction or projection record"], "serial": True, "identity_strategy": f"Assessment ID plus independent subject-version, definition, observation, result, verdict or artifact ID for {fid}; title, date, URL, score and digest never identify the assessment alone.", "source_refs": refs}],
            "inline_only_rationale": None}

def structure():
    bundles = []
    n = 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            findings = []
            for item in items:
                n += 1
                findings.append(finding(item, n, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups source-qualified assessment context for {lname.lower()}.", "source_refs": refs, "findings": findings})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed data-quality context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({r for layer in layers for r in layer[2]}), "layers": rendered})
    return {"bundles": bundles}

